@Test public void testSlayersCleaver(){
  addCard(Zone.BATTLEFIELD,playerA,"Slayer's Cleaver");
  addCard(Zone.BATTLEFIELD,playerA,"Mountain",4);
  addCard(Zone.BATTLEFIELD,playerA,"Memnite");
  addCard(Zone.BATTLEFIELD,playerB,"Dimensional Infiltrator");
  addCard(Zone.BATTLEFIELD,playerB,"Llanowar Elves");
  activateAbility(1,PhaseStep.PRECOMBAT_MAIN,playerA,"Equip","Memnite");
  attack(1,playerA,"Memnite");
  block(1,playerB,"Llanowar Elves","Memnite");
  setStopAt(1,PhaseStep.END_COMBAT);
  execute();
  assertPermanentCount(playerA,"Slayer's Cleaver",1);
  assertLife(playerB,20);
  assertGraveyardCount(playerA,"Memnite",1);
  assertGraveyardCount(playerB,"Dimensional Infiltrator",1);
  assertGraveyardCount(playerB,"Llanowar Elves",1);
}
